import { describe, expect, it } from "vitest";
import { moveStringToRear } from "../../../src/domain/textParsing/moveStringToRear.js";

// Reference outputs generated by running the live utils.py move_string_to_rear()
// against the same inputs (see conversation history / commit message).
describe("domain/textParsing/moveStringToRear parity with Python", () => {
  const cases: [string, string][] = [
    ["20mm anti infantry flak gun emg unemplaced", "20mm anti infantry flak gun emg "],
    ["20mm anti infantry flak gun emg emplaced", "20mm anti infantry flak gun emg  emplaced"],
    ["trench tier 2", "trench  t2"],
    ["bunker concrete", "bunker  t3"],
    ["infantry gun t3", "infantry gun  t3"],
    ["entrenched howitzer", " howitzer emplaced"],
  ];

  it.each(cases)("moveStringToRear(%j) === %j", (input, expected) => {
    expect(moveStringToRear(input)).toBe(expected);
  });
});
